.shd-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.shd-root,.shd-root *,.shd-root *::before,.shd-root *::after{box-sizing:border-box}
.shd-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.shd-root img{display:block;border:0;max-width:none}
.shd-root [hidden]{display:none!important}
.shd-root [data-sh-theme="light"]{display:none!important}
.shd-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.shd-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.shd-root .n81_11{position:absolute;display:contents;left:1516px;top:114px}
.shd-root .n71_2525{word-break:break-word;position:absolute;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;inset:11.3% 18.85% 87.41% 78.96%;line-height:14px;font-style:normal;color:var(--wa-point, #91c3f5);font-size:12px;text-align:center;white-space:nowrap;width:42px}
.shd-root .n71_2527{position:absolute;background-color:var(--wa-surface, #081b32);align-content:stretch;display:flex;height:30px;align-items:center;justify-content:center;left:1578px;border-bottom-left-radius:12px;border-bottom-right-radius:30px;border-top-right-radius:30px;top:114px;width:150px}
.shd-root .n76_185{word-break:break-word;font-family:"Inter","Pretendard",system-ui,sans-serif;font-weight:400;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:12px;text-align:center;color:var(--wa-text, #fff);white-space:nowrap;width:68px}
.shd-root [data-node-id="71:2531"]{border-color:transparent!important}
.shd-root [data-node-id="71:2531"]::after{content:"";position:absolute;inset:0px;border-radius:inherit;padding:1.5px;pointer-events:none;-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;background:linear-gradient(90deg,var(--wa-point, #6cabf3) 0%,var(--wa-point, #bcbcff) 50%,var(--wa-point, #7e91cd) 100%)}
.shd-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.shd-root[data-theme="light"] [data-name^="Screen/"] > [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.shd-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.shd-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.shd-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.shd-root[data-theme="light"] .n71_2525{color:var(--wa-point, #0e579f)}
